create schema if not exists auth;
create table auth.users(id uuid primary key);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid', true), '')::uuid $$;
do $$ begin create role authenticated; exception when duplicate_object then null; end $$;
do $$ begin create role anon; exception when duplicate_object then null; end $$;
create type public.app_role as enum ('admin','user');
create table public.user_roles(user_id uuid, role public.app_role);
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create table public.question_support_texts(id uuid primary key default gen_random_uuid(), body text);
create table public.official_exam_questions(id uuid primary key default gen_random_uuid(), contest_name text, exam_year int, exam_board text, question_text text, official_answer text, support_text_id uuid, content_status text default 'active');
create table public.board_exam_questions(id uuid primary key default gen_random_uuid(), board text, contest_name text, career_name text, exam_year int, item_number int, support_text text, stem text, options jsonb, official_answer text, content_status text default 'active');
create table public.curated_question_catalog(id uuid primary key default gen_random_uuid(), official_answer text, content_status text default 'active');
create table public.question_training_responses(id uuid primary key default gen_random_uuid(), user_id uuid, question_id uuid, question_source text, selected_answer text, asked_for_help boolean default false, response_seconds int default 10, created_at timestamptz default now());
create table public.simulator_attempts(id uuid primary key default gen_random_uuid(), user_id uuid, duration_seconds int, finished_at timestamptz default now());
create table public.simulator_responses(id uuid primary key default gen_random_uuid(), attempt_id uuid, user_id uuid, question_id uuid, selected_answer text);
create table public.study_sessions(user_id uuid, study_date date, active_seconds int, started_at timestamptz);
create table public.flashcard_reviews(user_id uuid, card_id uuid, rating text, reviewed_at timestamptz);
create table public.user_essays(user_id uuid, body text, created_at timestamptz);
